css:
.pl-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.pl-stage canvas { touch-action: none; cursor: grab; }
.pl-stage canvas.holding { cursor: grabbing; }
.pl-board { display: grid; gap: 3px; font-size: 15px; background: #f6f8fc; border: 2px solid #c9d3e6; border-radius: 12px; padding: 6px 10px; }
.pl-total { margin: 0 0 2px; font-size: 18px; }
.pl-total b { color: #c0392b; font-size: 22px; }
.pl-total span { color: #5a6478; font-size: 15px; }
.pl-row { display: grid; grid-template-columns: 9.5em 1fr; align-items: center; gap: 6px; }
.pl-row small { margin-left: 4px; color: #7a8399; font-size: 12px; }
.pl-row i { display: block; height: 12px; border-radius: 5px; background: linear-gradient(90deg, #e2481c var(--v), #e4e8f0 var(--v)); }
.pl-out { margin: 0; font-size: 17px; line-height: 1.45; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 6px 12px; min-height: 3.2em; }
.pl-ask { margin: 0; font-size: 15px; line-height: 1.4; padding: 5px 10px; border-left: 5px solid var(--accent); background: #f3f6fb; border-radius: 0 10px 10px 0; }

